 private string $dir;
 public function __construct(private PDO $db,private Repository $repo,private array $config,private ?\Closure $migrator=null){$this->dir=Config::storage().'/upgrades';}
 private function read():array{$p=$this->dir.'/state.json';return is_file($p)?json_decode((string)file_get_contents($p),true,32,JSON_THROW_ON_ERROR):['revision'=>0,'status'=>'idle','requests'=>[]];}
