 public function preflight():array{$checks=[];$add=function(string$id,bool$ok,string$detail)use(&$checks){$checks[]=['id'=>$id,'ok'=>$ok,'detail'=>$detail];};$add('php',PHP_VERSION_ID>=80300,'PHP 8.3 or newer');foreach(['pdo_mysql','mbstring','curl','intl','json','fileinfo']as$extension)$add('extension-'.$extension,extension_loaded($extension),$extension);try{$this->db->query('SELECT 1');$add('database',true,'Database connection available; migration privileges are verified only during apply.');}catch(\Throwable){$add('database',false,'Database unavailable.');}$storage=realpath(Config::storage());$public=realpath(dirname(__DIR__).'/public');$add('storage',$storage!==false&&is_writable($storage)&&($public===false||($storage!==$public&&!str_starts_with($storage,$public.'/'))),'Writable private storage outside the public web root');$add('release',$this->target()!=='','Local generated release manifest');$languages=true;try{$settings=$this->repo->setting('localization',Translations::defaults());$required=[$settings['defaultLocale']??'en',$settings['sourceLocale']??'tr'];foreach($settings['locales']??[]as$row)if(($row['enabled']??false)===true)$required[]=$row['code']??'';$baseline=json_decode((string)file_get_contents(dirname(__DIR__).'/resources/ui.en.json'),true,64,JSON_THROW_ON_ERROR);foreach(array_unique($required)as$locale){if(!is_string($locale)||!preg_match('/^[a-z]{2,3}(?:-[A-Z]{2})?$/D',$locale)||!Localization::complete($locale)){$languages=false;continue;}$package=LanguagePacks::runtimePackage($locale);$ui=$package['ui']??json_decode((string)file_get_contents(dirname(__DIR__).'/resources/ui.'.$locale.'.json'),true,64,JSON_THROW_ON_ERROR);if(!is_array($ui['messages']??null)||array_diff(array_keys($baseline['messages']),array_keys($ui['messages'])))$languages=false;else foreach($ui['messages']as$message)if(!is_string($message)||trim($message)==='')$languages=false;}}catch(\Throwable){$languages=false;}$add('language-packs',$languages,'Restore matching UI, content and server resources for every enabled language before applying. Do not replace missing translations with another language.');return ['ready'=>!in_array(false,array_column($checks,'ok'),true),'checks'=>$checks];}
 public function state():array{$s=$this->read();unset($s['requests']);return array_merge($s,['installedVersion'=>$this->repo->setting('installed-schema-version','unrecorded'),'targetVersion'=>$this->target(),'preflight'=>$this->preflight()]);}
