 private function lock():mixed{if(!is_dir($this->dir)&&!mkdir($this->dir,0700,true))throw new ApiException('Cannot create private upgrade storage.',503);if(is_link($this->dir))throw new ApiException('Upgrade storage cannot be a symlink.');chmod($this->dir,0700);$f=fopen($this->dir.'/lock','c');if(!$f||!flock($f,LOCK_EX|LOCK_NB))throw new ApiException('Another upgrade action is running.',409);chmod($this->dir.'/lock',0600);return $f;}
 public function change(array $input):array{
