  try{$s=$this->read();$hash=hash('sha256',json_encode($input,JSON_THROW_ON_ERROR));foreach($s['requests']as$r)if($r['id']===$input['requestId']){if($r['hash']!==$hash)throw new ApiException('Request ID was used for a different action.',409);return $this->state();}if($s['revision']!==$input['revision'])throw new ApiException('Upgrade state changed. Reload before continuing.',409);if($input['action']!=='recover')Validation::check($this->preflight()['ready'],'Upgrade preflight has unresolved checks.');
   if($input['action']==='recover'){$this->repo->transaction(fn()=>$this->repo->setSetting('upgrade-maintenance',false),true);$s['status']='failed';$s['error']='Interrupted maintenance gate cleared. Existing backups remain. Prepare a new backup before retrying; prior DDL may be partially applied.';}elseif($input['action']==='prepare'){Validation::check(count(glob($this->dir.'/*.json')?:[])<31,'Private upgrade backup archive is full. Archive old backups through hosting storage before preparing another.');
    $backup=$this->repo->exportBackup();$bytes=json_encode($backup,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);Validation::check(strlen($bytes)<=100*1024*1024,'Catalog backup exceeds the bounded wizard limit; use a hosting database backup.');$id=bin2hex(random_bytes(16));$this->privateWrite($this->dir.'/'.$id.'.json',$bytes);$s['receipt']=['id'=>$id,'sha256'=>hash('sha256',$bytes),'bytes'=>strlen($bytes),'createdAt'=>Repository::now(),'sourceFingerprint'=>self::fingerprint($backup),'sourceVersion'=>$this->repo->setting('installed-schema-version','unrecorded'),'targetVersion'=>$this->target()];$s['status']='prepared';unset($s['error']);$this->repo->audit('upgrade-prepare',$id,$s['receipt']['sha256']);
   }else{
    Validation::check($s['status']==='prepared','Prepare a new verified backup before applying.');$receipt=$s['receipt'];Validation::check(($input['receiptId']??null)===$receipt['id']&&($input['sha256']??null)===$receipt['sha256'],'Prepared backup receipt does not match.');Validation::check($receipt['targetVersion']===$this->target(),'Local release changed. Prepare a new backup.');$this->download($receipt['id']);
    $this->repo->transaction(function()use($receipt){$snapshot=$this->repo->exportBackup();if(!hash_equals($receipt['sourceFingerprint'],self::fingerprint($snapshot)))throw new ApiException('Catalog changed after backup. Prepare a new backup.',409);$this->repo->setSetting('upgrade-maintenance',true);},true);
    $s['status']='applying';$s['revision']++;$s['requests'][]=['id'=>$input['requestId'],'hash'=>$hash];$this->write($s);
    try{if($this->migrator)($this->migrator)($this->db);else {Database::migrate($this->db);(new CatalogQuery($this->db,$this->repo))->rebuild();}$this->repo->setSetting('installed-schema-version',$receipt['targetVersion']);$this->repo->audit('upgrade-apply',$receipt['id'],$receipt['targetVersion']);$s['status']='applied';$s['appliedAt']=Repository::now();unset($s['error']);}catch(\Throwable){$s['status']='failed';$s['error']='Database migration did not finish. Some DDL changes may already be applied. The private backup is retained; inspect hosting logs before preparing another attempt.';}finally{$this->repo->setSetting('upgrade-maintenance',false);$s['revision']++;$this->write($s);}return $this->state();
   }
   $s['revision']++;$s['requests']=array_slice(array_merge($s['requests'],[['id'=>$input['requestId'],'hash'=>$hash]]),-30);$this->write($s);return $this->state();
  }finally{flock($lock,LOCK_UN);fclose($lock);}
 }
 public function download(string $id):string{$s=$this->read();$r=$s['receipt']??null;Validation::check(preg_match('/^[a-f0-9]{32}$/D',$id)&&$r&&hash_equals($r['id'],$id),'Backup receipt not found.');$p=$this->dir.'/'.$id.'.json';Validation::check(is_file($p)&&!is_link($p)&&filesize($p)===$r['bytes'],'Prepared backup is missing or changed.');$bytes=(string)file_get_contents($p);Validation::check(hash_equals($r['sha256'],hash('sha256',$bytes)),'Prepared backup integrity check failed.');return $bytes;}
}
